begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d1111000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','route-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Routed fixture"}',now(),now()from generate_series(1,6)n;
create temp table rr(k text primary key,v uuid);
insert into rr select 'u'||n,p.id from generate_series(1,6)n join public.participants p on p.auth_user_id=('d1111000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
grant all on rr to authenticated;
create function pg_temp.rid(k text)returns uuid language sql as $$select v from rr where rr.k=$1$$;
create function pg_temp.rclaim(n int)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','d1111000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',false)::text,true);end$$;
create function pg_temp.rpayment(k text,p int,r int,amount bigint,via int default null,route bigint default null,c text default 'VND')returns jsonb language sql as $$select jsonb_build_object('id',k,'payer',pg_temp.rid('u'||p),'recipient',pg_temp.rid('u'||r),'tenderCurrency',c,'tenderMinor',amount,'method',case when c='MYR'then'bank_transfer'else'cash'end)||case when via is null then'{}'::jsonb else jsonb_build_object('via',jsonb_build_object('person',pg_temp.rid('u'||via),'minor',route))end$$;
create function pg_temp.rdraft(rows jsonb)returns jsonb language sql as $$select jsonb_build_object('rateMode','custom','vndPerMyr','6000','payments',rows)$$;
create function pg_temp.rbill(trip uuid,creditor int,debtor int,n bigint,c text default 'VND')returns uuid language plpgsql as $$declare e jsonb;begin e:=public.create_trip_expense_editor(gen_random_uuid(),trip,jsonb_build_object('expense_scope','space','target_space_id',trip,'participant_ids',array[pg_temp.rid('u'||creditor),pg_temp.rid('u'||debtor)],'contribution_amounts',array[n,0],'share_amounts',array[0,n],'total_minor',n,'currency_code',c,'description','Routed fixture','category','Food','occurred_on','2026-11-10'),array[pg_temp.rid('u'||creditor),pg_temp.rid('u'||debtor)]);return(e->>'expense_id')::uuid;end$$;
set local role authenticated;
select pg_temp.rclaim(2);
insert into rr values('trip',public.create_space('trip','Routed isolated',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)select pg_temp.rid('trip'),pg_temp.rid('u'||n),'view'from unnest(array[1,3,4,5])n;
set local role authenticated;
select pg_temp.rclaim(2);
select pg_temp.rbill(pg_temp.rid('trip'),2,1,280000),pg_temp.rbill(pg_temp.rid('trip'),2,5,100000),pg_temp.rbill(pg_temp.rid('trip'),3,2,400000),pg_temp.rbill(pg_temp.rid('trip'),4,2,100000),pg_temp.rbill(pg_temp.rid('trip'),3,1,250000),pg_temp.rbill(pg_temp.rid('trip'),4,1,20000),pg_temp.rbill(pg_temp.rid('trip'),3,5,260000);
select pg_temp.rclaim(1);
insert into rr values('ps-account',(public.create_personal_account(gen_random_uuid(),'PS VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(3);
insert into rr values('dav-account',(public.create_personal_account(gen_random_uuid(),'Dav VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(4);
insert into rr values('alex-account',(public.create_personal_account(gen_random_uuid(),'Alex VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(5);
insert into rr values('exson-account',(public.create_personal_account(gen_random_uuid(),'Exson VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(1);
create temp table rv(k text primary key,v jsonb);
insert into rv values('draft',pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('dav',1,3,400000,2,200000),pg_temp.rpayment('alex',1,4,100000,2,80000))));
insert into rv values('preview',public.preview_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='draft')));
select is(jsonb_array_length((select v->'plan'->'issues'from rv where k='preview')),0,'two recipients share one upstream cap exactly');
select ok(not((select v->'plan'from rv where k='preview') ?|array['native','sources','actors','accounts']),'public preview excludes native IDs, accounts and internal approval identities');
select ok(exists(select 1 from jsonb_array_elements(public.preview_trip_routed_settlement(pg_temp.rid('trip'),pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('dav',1,3,400000,2,200000),pg_temp.rpayment('alex',1,4,120000,2,100000))))->'plan'->'issues')q where q->>'code'='SHARED_LIMIT'and jsonb_array_length(q->'paymentIds')=2),'upstream cap reports both affected payment rows');
select pg_temp.rclaim(3);
select ok(exists(select 1 from jsonb_array_elements(public.preview_trip_routed_settlement(pg_temp.rid('trip'),pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('ps',1,3,400000,2,250000),pg_temp.rpayment('exson',5,3,300000,2,200000))))->'plan'->'issues')q where q->>'code'='SHARED_LIMIT'and jsonb_array_length(q->'paymentIds')=2),'downstream cap is shared across payers');
select throws_ok($$select public.preview_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'))$$,'P0001','routed_participant_denied','Dav cannot also record an unrelated payment to Alex');
select pg_temp.rclaim(2);
select throws_ok($$select public.preview_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'))$$,'P0001','routed_participant_denied','Trip owner cannot forge actual payer/recipient authority');
select pg_temp.rclaim(1);
insert into rr values('request',gen_random_uuid());
insert into rv values('submitted',public.submit_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview')));
insert into rr values('proposal',((select v->>'id'from rv where k='submitted'))::uuid);
select is((select v->>'status'from rv where k='submitted'),'pending','submit is pending, not an assumed transfer');
select is((public.submit_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview'))->>'id')::uuid,pg_temp.rid('proposal'),'same actor/request returns identical proposal');
select throws_ok($$select public.submit_trip_routed_settlement(pg_temp.rid('trip'),(select v||'{"vndPerMyr":"6001"}'from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview'))$$,'P0001','idempotency_conflict','same request with changed content conflicts');
select is((select count(*)::int from public.settlement_payments where space_id=pg_temp.rid('trip')),0,'preview and submit post no funds or debt');
select is((public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',1,jsonb_build_object('dav:payer',pg_temp.rid('ps-account'),'alex:payer',pg_temp.rid('ps-account')))->>'approvedCount')::int,1,'payer explicitly authorizes own accounts');
select is((public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',1,jsonb_build_object('dav:payer',pg_temp.rid('ps-account'),'alex:payer',pg_temp.rid('ps-account')))->>'approvedCount')::int,1,'duplicate payer approval is idempotent');
select pg_temp.rclaim(5);
select is(jsonb_array_length(public.read_trip_routed_settlements(pg_temp.rid('trip'))),0,'uninvolved member sees no proposal graph');
select throws_ok($$select public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',2,'{}')$$,'P0001','settlement_participant_denied','uninvolved member cannot confirm');
select pg_temp.rclaim(3);
select throws_ok($$select public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',2,jsonb_build_object('dav:receiver',pg_temp.rid('ps-account')))$$,'P0001','settlement_cash_account_invalid','receiver cannot select payer account');
select public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',2,jsonb_build_object('dav:receiver',pg_temp.rid('dav-account')));
select pg_temp.rclaim(4);
select public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',3,jsonb_build_object('alex:receiver',pg_temp.rid('alex-account')));
reset role;
create function pg_temp.reject_routed_entry()returns trigger language plpgsql as $$begin if current_setting('tabby.test_routed_fail',true)='on'then raise exception 'isolated_rollback_probe';end if;return new;end$$;
create trigger routed_test_failure before insert on public.personal_account_entries for each row execute function pg_temp.reject_routed_entry();
set local role authenticated;
select pg_temp.rclaim(2);
select set_config('tabby.test_routed_fail','on',true);
select throws_ok($$select public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',4,'{}')$$,'P0001','isolated_rollback_probe','failure in cash posting rolls back the whole final confirmation');
select set_config('tabby.test_routed_fail','off',true);
select is((public.read_trip_routed_settlements(pg_temp.rid('trip'))->0->>'approvedCount')::int,3,'failed final approval is rolled back');
select is((select count(*)::int from public.settlement_payments where space_id=pg_temp.rid('trip')),0,'failed transaction leaves no cash, coverage or receipts');
select is(public.decide_trip_routed_settlement(pg_temp.rid('proposal'),'approve',4,'{}')->>'status','posted','last required actor posts all cash and coverage atomically');
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('ps-account')),-500000::bigint,'PS pays two recipients once');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('dav-account')),400000::bigint,'Dav receives only Dav cash');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('alex-account')),100000::bigint,'Alex receives only Alex cash');
select is((select count(*)::int from public.personal_settlement_cash_legs where owner_participant_id=pg_temp.rid('u2')),0,'intermediary receives no synthetic cash');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u1'),pg_temp.rid('u2'),'VND'),0::bigint,'shared PS to Lii source reduced exactly once');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u1'),pg_temp.rid('u3'),'VND'),50000::bigint,'route is consumed before PS direct debt');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u2'),pg_temp.rid('u4'),'VND'),20000::bigint,'unpaid Lii to Alex remains outstanding');
-- A second payer pays only Dav; Alex is untouched.
set local role authenticated;
select pg_temp.rclaim(5);
insert into rv values('ex-draft',pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('dav-only',5,3,300000,2,100000))));
insert into rv values('ex-preview',public.preview_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='ex-draft')));
insert into rr values('ex-proposal',(public.submit_trip_routed_settlement(pg_temp.rid('trip'),(select v from rv where k='ex-draft'),gen_random_uuid(),(select v->>'digest'from rv where k='ex-preview'),(select(v->>'expiresAt')::timestamptz from rv where k='ex-preview'))->>'id')::uuid);
select public.decide_trip_routed_settlement(pg_temp.rid('ex-proposal'),'approve',1,jsonb_build_object('dav-only:payer',pg_temp.rid('exson-account')));
select pg_temp.rclaim(3);
select public.decide_trip_routed_settlement(pg_temp.rid('ex-proposal'),'approve',2,jsonb_build_object('dav-only:receiver',pg_temp.rid('dav-account')));
select pg_temp.rclaim(2);
select is(public.decide_trip_routed_settlement(pg_temp.rid('ex-proposal'),'approve',3,'{}')->>'status','posted','single-recipient route posts independently');
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('dav-account')),700000::bigint,'Dav total is actual 700000 VND');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('alex-account')),100000::bigint,'paying only Dav does not increase Alex cash');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u2'),pg_temp.rid('u4'),'VND'),20000::bigint,'paying only Dav does not settle Alex debt');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u5'),pg_temp.rid('u3'),'VND'),60000::bigint,'Exson direct remainder matches product fixture');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u2'),pg_temp.rid('u3'),'VND'),100000::bigint,'Lii downstream remainder matches product fixture');
set local role authenticated;
select pg_temp.rclaim(1);
select throws_ok($$select public.reverse_trip_routed_settlement(pg_temp.rid('proposal'),gen_random_uuid(),5)$$,'P0001','routed_reversal_dependency','dependent downstream settlement blocks earlier whole reversal');
select pg_temp.rclaim(5);
select is(public.reverse_trip_routed_settlement(pg_temp.rid('ex-proposal'),gen_random_uuid(),4)->>'status','reversed','whole cash and route reversal succeeds in dependency order');
select pg_temp.rclaim(1);
insert into rr values('reverse-request',gen_random_uuid());
select is(public.reverse_trip_routed_settlement(pg_temp.rid('proposal'),pg_temp.rid('reverse-request'),5)->>'status','reversed','whole dual-recipient proposal reverses together');
select is(public.reverse_trip_routed_settlement(pg_temp.rid('proposal'),pg_temp.rid('reverse-request'),5)->>'status','reversed','reversal request replay does not reverse twice');
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('ps-account')),0::bigint,'all PS cash is restored');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u1'),pg_temp.rid('u2'),'VND'),280000::bigint,'whole original upstream debt restored');
select ok(not has_function_privilege('anon','public.preview_trip_routed_settlement(uuid,jsonb,timestamptz)','EXECUTE'),'anonymous preview denied');
select ok(not has_function_privilege('authenticated','private.post_routed_proposal(uuid)','EXECUTE'),'private posting cannot be called from client');
select ok(not has_table_privilege('authenticated','private.trip_routed_proposals','SELECT'),'private native snapshots denied to client');
select is((select count(*)::int from pg_class where oid in('private.trip_routed_proposals'::regclass,'private.trip_routed_approvals'::regclass,'private.trip_routed_receipts'::regclass)and relrowsecurity),3,'all new private financial tables have RLS');
select * from finish();
rollback;
